package com.inventra.backend.service; import com.inventra.backend.dto.*; import com.inventra.backend.model.Product; import com.inventra.backend.repository.ProductRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class RecommendationService {private final ProductRepository repo;private final ForecastService forecast;public RecommendationService(ProductRepository r,ForecastService f){repo=r;forecast=f;}public List<RecommendationResponse> recommend(String productId){Product target=repo.findById(productId).orElseThrow(()->new IllegalArgumentException("Product not found"));double demand;try{demand=forecast.forecast(productId,30).getPredictedDailyDemand();}catch(Exception e){demand=0;}final double predictedDemand = demand;return repo.findAll().stream().filter(p->p.getCategory()!=null&&p.getCategory().equalsIgnoreCase(target.getCategory())&&!p.getId().equals(target.getId())).sorted(Comparator.comparingInt(Product::getStockQuantity)).limit(5).map(p->new RecommendationResponse(p.getId(),p.getSku(),p.getName(),p.getCategory(),p.getPrice(),p.getStockQuantity(),p.getReorderLevel(),predictedDemand,Math.max(0,p.getReorderLevel()-p.getStockQuantity()),p.getStockQuantity()<=p.getReorderLevel()?"Similar category item is low in stock.":"Recommended as a related category item.")).toList();}}
